from __future__ import annotations

import pandas as pd
import pytest

from ml_workbench.rules.eda import (
    EDA_MAX_ROWS,
    base_views,
    categorical_cardinalities,
    eda_plan,
    sample_frame_for_eda,
    skew_hint,
    task_views,
)
from ml_workbench.state import TaskDefinition


def _task(task_type: str, *, learning_type: str = "supervised") -> TaskDefinition:
    return TaskDefinition(
        learning_type=learning_type,
        task_type=task_type,
        target=None if learning_type == "unsupervised" else "y",
        time_column="date" if task_type == "forecasting" else None,
    )


def test_eda_base_views_all_tasks() -> None:
    assert base_views() == ("shape", "dtypes", "missing_heatmap", "distributions", "correlation")
    for task_type in ("binary", "regression", "forecasting", "clustering"):
        plan = eda_plan(_task(task_type))
        assert set(plan) >= set(base_views())


def test_eda_classification_views() -> None:
    for task_type in ("binary", "multiclass", "multilabel"):
        views = task_views(_task(task_type))
        assert "class_balance" in views
        assert "feature_by_class" in views
        assert "chi_square" in views
    assert "decomposition" not in task_views(_task("binary"))


def test_eda_regression_views_skew_hint() -> None:
    views = task_views(_task("regression"))
    assert "target_histogram" in views
    assert "qq_plot" in views
    assert "feature_target_scatter" in views
    skewed = pd.Series([1.0, 1.2, 1.1, 1.5, 2.0, 4.0, 9.0, 40.0])
    hint = skew_hint(skewed)
    assert hint is not None
    assert "log transform is suggested" in hint
    balanced = pd.Series([1.0, 2.0, 3.0, 4.0, 3.0, 2.0])
    assert skew_hint(balanced) is None


